-- Idempotent seed for local dev.
-- Harbourline Bank (fictional). Fixed UUIDs so re-runs are safe.

BEGIN;

VALUES ('11111111-1111-7111-8111-111111111111', 'harbourline', 'Harbourline Bank', 'expedition-atlas')
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT (id) DO NOTHING;

UPDATE users SET manager_id = '44444444-0000-7000-8000-000000000004'
  WHERE id IN ('44444444-0000-7000-8000-000000000006','44444444-0000-7000-8000-000000000007','44444444-0000-7000-8000-00000000000a');
UPDATE users SET manager_id = '44444444-0000-7000-8000-000000000005'
