  WHERE id IN ('44444444-0000-7000-8000-000000000009','44444444-0000-7000-8000-00000000000c');

   '44444444-0000-7000-8000-000000000001', '33333333-0000-7000-8000-000000000007', 'tenant', NULL),
  ('55555555-0000-7000-8000-000000000002', '11111111-1111-7111-8111-111111111111',
   '44444444-0000-7000-8000-000000000001', '33333333-0000-7000-8000-000000000005', 'tenant', NULL),
  ('55555555-0000-7000-8000-000000000003', '11111111-1111-7111-8111-111111111111',
   '44444444-0000-7000-8000-000000000005', '33333333-0000-7000-8000-000000000005', 'tenant', NULL),
  ('55555555-0000-7000-8000-000000000004', '11111111-1111-7111-8111-111111111111',
   '44444444-0000-7000-8000-000000000002', '33333333-0000-7000-8000-000000000006', 'tenant', NULL),
  ('55555555-0000-7000-8000-000000000005', '11111111-1111-7111-8111-111111111111',
   '44444444-0000-7000-8000-000000000003', '33333333-0000-7000-8000-000000000003', 'tenant', NULL),
  ('55555555-0000-7000-8000-000000000006', '11111111-1111-7111-8111-111111111111',
