SELECT gen_random_uuid(), '11111111-1111-7111-8111-111111111111', u.id,
       '33333333-0000-7000-8000-000000000001', 'tenant', NULL
FROM users u
WHERE u.tenant_id = '11111111-1111-7111-8111-111111111111'
