COMMIT;

SELECT
  (SELECT count(*) FROM users       WHERE tenant_id = '11111111-1111-7111-8111-111111111111') AS users,
  (SELECT count(*) FROM departments WHERE tenant_id = '11111111-1111-7111-8111-111111111111') AS departments,
  (SELECT count(*) FROM roles       WHERE tenant_id = '11111111-1111-7111-8111-111111111111') AS roles,
  (SELECT count(*) FROM user_roles  WHERE tenant_id = '11111111-1111-7111-8111-111111111111') AS role_assignments;